begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
insert into public.entries(id,owner_id,title,body) values('93000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001',null,'今天学了为什么牙套能移动牙齿。');
set local role service_role;
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',false)->>'claimed','true','First request acquires generation');
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',false)->>'claimed','false','Duplicate request cannot generate again');
select throws_ok($$select public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000099','93000000-0000-4000-8000-000000000001',1,'classification',false)$$,'P0001','entry_changed','Other owner cannot request source content');
select throws_ok($$select public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',2,'classification',false)$$,'P0001','entry_changed','Stale version refused');
update public.ai_suggestions set started_at=now()-interval '3 minutes' where entry_id='93000000-0000-4000-8000-000000000001';
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',false)->'suggestion'->>'status','failed','Expired request visible as failed');
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',false)->>'claimed','false','No automatic paid retry');
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',true)->>'claimed','true','Explicit retry permitted');
update public.ai_suggestions set status='proposed',suggestions='{"title":"Learning"}' where entry_id='93000000-0000-4000-8000-000000000001';
select is(public.claim_entry_ai_suggestion('10000000-0000-0000-0000-000000000001','93000000-0000-4000-8000-000000000001',1,'classification_tagging',true)->>'claimed','false','Successful suggestion remains cached');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.ai_suggestions where entry_id='93000000-0000-4000-8000-000000000001'),1::bigint,'Owner can read persisted suggestion');
select is(public.dismiss_ai_suggestion((select id from public.ai_suggestions where entry_id='93000000-0000-4000-8000-000000000001')),true,'Owner can dismiss');
select is((select title from public.entries where id='93000000-0000-4000-8000-000000000001'),null::text,'Suggestion never overwrites original title');
select is((select revision from public.entries where id='93000000-0000-4000-8000-000000000001'),1,'Suggestion never edits the Entry');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000099',true);
select is((select count(*) from public.ai_suggestions where entry_id='93000000-0000-4000-8000-000000000001'),0::bigint,'Other owner cannot read suggestions');
reset role;
select ok(not has_function_privilege('authenticated','public.claim_entry_ai_suggestion(uuid,uuid,integer,text,boolean)','execute'),'Generation claims are server-only');
select ok(not has_table_privilege('authenticated','public.ai_suggestions','update'),'Clients cannot forge model provenance');
select ok(not has_function_privilege('anon','public.dismiss_ai_suggestion(uuid)','execute'),'Anonymous dismissal denied');
select * from finish();
rollback;
